def transform(grid):
    out = [row[:] for row in grid]
    anchors = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    for r, c in anchors:
        for rr in (r - 1, r, r + 1):
            if 0 <= rr < len(out):
                out[rr][c] = 5
    return out
